function nearestBeacons(beacons, k) {
  const key = (p) => p[0] * p[0] + p[1] * p[1];
  return beacons.map(([x, y]) => [x, y])
    .sort((a, b) => key(a) - key(b) || a[0] - b[0] || a[1] - b[1])
    .slice(0, k);
}

function nearestBeacons(beacons, k) {
  const cmp = (a, b) => (a[0] * a[0] + a[1] * a[1]) - (b[0] * b[0] + b[1] * b[1]) || a[0] - b[0] || a[1] - b[1];
  const heap = [];
  const up = (i) => {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (cmp(heap[p], heap[i]) >= 0) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const down = (i) => {
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let top = i;
      if (l < heap.length && cmp(heap[l], heap[top]) > 0) top = l;
      if (r < heap.length && cmp(heap[r], heap[top]) > 0) top = r;
      if (top === i) return;
      [heap[top], heap[i]] = [heap[i], heap[top]];
      i = top;
    }
  };
  for (const [x, y] of beacons) {
    if (heap.length < k) { heap.push([x, y]); up(heap.length - 1); }
    else if (cmp([x, y], heap[0]) < 0) { heap[0] = [x, y]; down(0); }
  }
  return heap.sort(cmp);
}
